    'config.mcpserver.pinned_resources': "固定资源",
    'config.mcpserver.pinned_resources.help': "智能体启动时读取一次并注入系统提示的资源 URI，作为不可信的服务端上下文。服务未提供该资源，或工具策略拒绝时会跳过并警告；每个运行只读一次，不刷新、不订阅。",
    'config.mcpserver.tls_ca_cert_path': "CA 证书路径",
    'config.mcpserver.tls_ca_cert_path.help': "额外信任的 PEM CA 证书或证书包的绝对路径，用于此服务的 HTTP/SSE；证书和主机名校验仍然开启。必须是不超过 1 MiB 的普通文件，缺失、不可读、为空、过大或无效会直接连接失败，不会退回默认信任库。设置后 URL 和 SSE 消息端点必须使用 HTTPS，明文 URL 和降级重定向会被拒绝。stdio 忽略。",
