    'config.section.multimodal': "多模态",
    'config.section.multimodal.help': "图像附件处理。工具输出里的本地图片路径会变成 [IMAGE:...] 标记，并以 base64 内联进下一次供应商请求，原先留在本机的图片字节会被上传。max_images 限制单次请求的图片数量；对个人或敏感图片目录使用 shell 类工具时需注意这一上传行为。",
    'config.multimodal.max_images': "最大图片数",
    'config.multimodal.max_images.help': "单次请求最多保留多少张 [IMAGE:...] 图片，超出时先丢掉更早的；新图顶替所在消息里最早的一张时，可能使该消息之后的供应商前缀缓存失效。默认 4，满额后每张新图仍会淘汰一张，这也是工具带出本地图片时单轮上传成本的上限。",
    'config.multimodal.max_image_size_mb': "单张大小上限（MiB）",
    'config.multimodal.max_image_size_mb.help': "base64 编码前的单张上限，单位 MiB，按解码字节计算，编码后大约再大三分之一；适用于频道附件、工具带出的本地图片和网页控制台上传，默认 20（运行时夹在 1 到 20），调低可限制单轮上传或网关缓冲。Anthropic 另会拒绝单张 base64 超过 10 MB（约 7.5 MiB 解码后）的图片，由其客户端单独执行，与此项无关。",
    'config.multimodal.max_image_turns': "图片保留轮数",
    'config.multimodal.max_image_turns.help': "用户消息里的图片最多保留多少轮，超过后会在发给供应商前去掉，避免同一张截图在后续每一轮都被重新编码并上传。默认 0，表示不按轮数裁剪，只受 max_images 数量上限约束；工具结果里的图片不受此项影响。",
    'config.multimodal.allow_remote_fetch': "允许远程拉取",
